entries[21215] = { ["name"] = "Graccus hausgemachte Früchtepastete", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 787500 / 5 * 20) Gesundheit und ( 1050000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Außerdem solltet Ihr den Geschmack von Früchtepastete mögen.\n\"Mit Graccus Spezialgewürzen haltbar gemacht! Es wird eine ganze Weile dauern, bis das hier schlecht wird...\"\nVerkaufspreis:" }
