entries[21217] = { ["name"] = "Weisenfisch Supreme", ["text"] = "Benutzen: Stellt im Verlauf von 21 Sek. 922283 Gesundheit und 1382333 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 3 Mana.\nVerkaufspreis:" }
entries[21218] = { ["name"] = "Blauer Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier kann nur im Tempel von Ahn'Qiraj beschworen werden.\nStößt ein Hochfrequenzsignal aus, das eine Qirajipanzerdrohne dazu zwingt, sich aus dem Boden unter dem Tempel von Ahn'Qiraj an die Oberfläche zu graben. Der Silithid gehorcht seinem Beschwörer und kann innerhalb des Tempels von Ahn'Qiraj als Reittier benutzt werden. Jegliche feindseligen Handlungen gegen den Reiter zwingen die Qirajipanzerdrohne, sich wieder einzugraben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser (relativ) zahme Silithid haust ausschließlich in der sandigen Wüste von Ahn'Qiraj.\"\nBeute von:\nWeltbeute\nOrt:\nTempel von Ahn'Qiraj" }
entries[21219] = { ["name"] = "Rezept: Weisenfisch Supreme", ["text"] = "Benutzen: Lehrt Euch, wie man Weisenfisch Surpreme zubereitet.\nBenötigt Klassische Kochkunst (175)\nVerkaufspreis:\nWeisenfisch Supreme\nBenutzen: Stellt im Verlauf von 21 Sek. 922283 Gesundheit und 1382333 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 3 Mana.\nVerkaufspreis:\nBenötigt Roher großer Weisenfisch" }
